function icon(name) { return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.file}</svg>`; }
function escapeHTML(value = '') { return String(value).replace(/[&<>'"]/g, (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' }[c])); }
function slugify(value = '') { return String(value).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\u0900-\u097f]+/g,'-').replace(/^-|-$/g,'').slice(0,100); }
function formatDate(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('hi-IN',{day:'numeric',month:'short',year:'numeric'}).format(date); }
function sanitizeHTML(html = '') { if(window.DOMPurify)return window.DOMPurify.sanitize(html,{USE_PROFILES:{html:true}});const template=document.createElement('template');template.innerHTML=String(html);template.content.querySelectorAll('script,style,iframe,object,embed,form').forEach(n=>n.remove());template.content.querySelectorAll('*').forEach(n=>[...n.attributes].forEach(a=>{if(a.name.toLowerCase().startsWith('on')||['javascript:','data:text/html'].some(v=>a.value.trim().toLowerCase().startsWith(v)))n.removeAttribute(a.name);}));return template.innerHTML; }
